css:
.d-pl{width:100%;max-width:340px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-pl-now{display:flex;justify-content:space-between;align-items:baseline;padding:10px 12px;border-bottom:1px solid var(--line)}
.d-pl-now b{font-size:12px}
.d-pl-now span{font-family:var(--font-mono);font-size:9px;color:var(--faint)}
.d-pl-list{list-style:none;margin:0;padding:4px 0}
.d-pl-list li{display:flex;justify-content:space-between;padding:6px 12px;font-size:11px;color:var(--muted);cursor:pointer;border-left:2px solid transparent}
.d-pl-list li.d-pl-on{color:var(--ink);border-left-color:var(--ink);background:color-mix(in srgb,var(--ink) 5%,transparent)}
.d-pl-list em{font-style:normal;font-family:var(--font-mono);font-size:9px;color:var(--faint)}

init:
root => {
  var list = root.querySelector('[data-list]');
  var title = root.querySelector('[data-title]');
  var time = root.querySelector('[data-time]');
  if (!list) return;
  var items = [].slice.call(list.children), i = 0, t = 0, timer = 0;
  var fmt = function (s) { return '00:' + (s < 10 ? '0' : '') + s; };
  var paint = function () {
    items.forEach(function (li, k) { li.classList.toggle('d-pl-on', k === i); });
    if (title) title.textContent = items[i].firstChild.textContent.trim();
    if (time) time.textContent = fmt(Math.floor(t)) + ' / 00:' + String(items[i].dataset.d).padStart(2, '0');
  };
  var next = function () { i = (i + 1) % items.length; t = 0; paint(); };
  var start = function () { clearInterval(timer); timer = setInterval(function () { t += .25; if (t >= Number(items[i].dataset.d)) next(); paint(); }, 250); };
  items.forEach(function (li, k) { li.addEventListener('click', function () { i = k; t = 0; paint(); start(); }); });
  paint(); start();
}
